package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var t int
	fmt.Fscan(in, &t)

	aa := make([]int, t)
	for i := 0; i < t; i++ {
		fmt.Fscan(in, &aa[i])
	}

	a, b := 1, 2
	flag := false

	for _, x := range aa {
		if x == a {
			b = 6 - (a + b)
		} else if x == b {
			a = 6 - (a + b)
		} else {
			flag = true
			break
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	if flag {
		fmt.Fprintln(out, "NO")
	} else {
		fmt.Fprintln(out, "YES")
	}
}

